import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, oneMinus, length, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CylinderGeometry,
    Color,
    Box3,
    Vector3,
    PointLight,
    DirectionalLight,
  } = THREE;

  const root = new Group();
  root.name = 'orbit-product-hero';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const cSurface = new Color(colors.surface ?? '#14141a');
  const cPaper = colors.paper ?? '#e8ecf2';
  const cAccent = new Color(colors.accent ?? '#ff2a38');
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ------------------------------------------------------------------
  // BACKDROP — enlarged to fill the hub frame at z=-2.5 so no raw black
  // void survives at the frame edges. Engineered vertical gradient from
  // spec stops, with a restrained multiplicative pool of light behind
  // the subject (capped at 1.35x of a near-black base — cannot blow out)
  // and a vignette that only darkens toward the edges.
  // ------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(15, 12);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const g0 = new Color(gradientStops[0]?.hex ?? '#0b0b10');
    const g1 = new Color(gradientStops[1]?.hex ?? '#101017');
    const g2 = new Color(gradientStops[2]?.hex ?? '#16161d');
    const stop0 = float(gradientStops[0]?.at ?? 0.0);
    const stop1 = float(gradientStops[1]?.at ?? 0.55);
    const stop2 = float(gradientStops[2]?.at ?? 1.0);
    const v = uv().y;
    const c0 = vec3(g0.r, g0.g, g0.b);
    const c1 = vec3(g1.r, g1.g, g1.b);
    const c2 = vec3(g2.r, g2.g, g2.b);
    const lower = mix(c0, c1, smoothstep(stop0, stop1, v));
    const full = mix(lower, c2, smoothstep(stop1, stop2, v));
    const centerDist = length(uv().sub(0.5));
    const pool = oneMinus(smoothstep(float(0.06), float(0.42), centerDist));
    const vignette = oneMinus(smoothstep(float(0.35), float(0.75), centerDist)).mul(0.45).add(0.55);
    backdropMat.colorNode = full.mul(pool.mul(0.35).add(1.0)).mul(vignette);
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ------------------------------------------------------------------
  // LIGHTS — directional rims so the brushed case reads with crisp edge
  // highlights (points alone left the metal dead-flat last pass).
  // Accent red rim grazes the LEFT case flank per spec; cool paper rim
  // from back-right shapes the bezel. Scene supplies ambient 0.6 + key
  // 1.2 — all local intensities stay <= 1.5, no light exceeds doctrine.
  // ------------------------------------------------------------------
  const rimRed = new DirectionalLight(cAccent.getHex(), 1.0);
  rimRed.position.set(-3.4, 0.7, -1.6);
  rimRed.target.position.set(0, -0.1, 0);
  root.add(rimRed);
  root.add(rimRed.target);

  const rimCool = new DirectionalLight(0xe8ecf2, 0.7);
  rimCool.position.set(3.2, 2.4, -2.2);
  rimCool.target.position.set(0, 0, 0);
  root.add(rimCool);
  root.add(rimCool.target);

  const frontFill = new PointLight(0xe8ecf2, 0.3, 8.0, 2.0);
  frontFill.position.set(0.9, -0.3, 2.6);
  root.add(frontFill);

  const accentKick = new PointLight(cAccent.getHex(), 0.25, 5.0, 2.0);
  accentKick.position.set(-1.6, -0.9, 1.4);
  root.add(accentKick);

  // ------------------------------------------------------------------
  // PLINTH — radius 1.4, height 0.25, top face at y=-1.1
  // ------------------------------------------------------------------
  const plinthGeo = new CylinderGeometry(1.4, 1.44, 0.25, 96, 1);
  const plinthMat = new MeshStandardNodeMaterial({
    color: cSurface.getHex(),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.1 - 0.125, 0);
  root.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // thin accent reveal ring on the plinth top edge — emissive cap 1.6 per spec
  const ringGeo = new CylinderGeometry(1.41, 1.41, 0.012, 96, 1, true);
  const ringMat = new MeshBasicNodeMaterial();
  ringMat.colorNode = vec3(cAccent.r, cAccent.g, cAccent.b).mul(1.6);
  const ring = new Mesh(ringGeo, ringMat);
  ring.position.set(0, -1.104, 0);
  root.add(ring);
  disposables.push(ringGeo, ringMat);

  // ------------------------------------------------------------------
  // CONTACT SHADOW — radial gradient plane radius 1.6, opacity 0.55
  // ------------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const falloff = oneMinus(smoothstep(float(0.15), float(1.0), d));
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = falloff.mul(0.55);
  }
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.348, 0);
  root.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ------------------------------------------------------------------
  // WATCH MESH — hero, 2.2 units tall, grade 5 titanium.
  // Fixes vs previous pass:
  //  1. CULL any large flat card/backdrop mesh baked into the GLB —
  //     that was the blown-white slab intruding on the left of frame.
  //  2. Opaque brushed-titanium StandardNodeMaterial (mid-gray albedo,
  //     TSL striated roughness for the brushed read) — no clearcoat, no
  //     physical transmission path, so it can never render as glass.
  //  3. Corrective uprighting rotation + re-seat so the case stands on
  //     the plinth instead of leaning.
  // ------------------------------------------------------------------
  const watchGroup = new Group();
  watchGroup.name = 'watch-hero';
  root.add(watchGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;
    const model = gltf.scene;

    // --- cull flat slab meshes (backdrop cards baked into the export) ---
    const rawBox = new Box3().setFromObject(model);
    const rawSize = new Vector3();
    rawBox.getSize(rawSize);
    const rawMax = Math.max(rawSize.x, rawSize.y, rawSize.z) || 1;
    model.traverse((child) => {
      if (!child.isMesh) return;
      const b = new Box3().setFromObject(child);
      const s = new Vector3();
      b.getSize(s);
      const dims = [s.x, s.y, s.z].sort((a, bb) => a - bb);
      if (dims[2] > 0.55 * rawMax && dims[0] < 0.05 * dims[2]) {
        child.visible = false; // plane-like slab: remove from the stage
      }
    });

    // --- brushed titanium material override ---
    model.traverse((child) => {
      if (!child.isMesh || !child.visible) return;
      const src = child.material || {};
      const mat = new MeshStandardNodeMaterial({
        color: 0x767b84, // grade 5 titanium — cool mid gray, never chalk-white
        metalness: 0.5,
      });
      // fine roughness striations = brushed machined finish
      mat.roughnessNode = positionLocal.y.mul(180.0).sin().mul(0.05).add(0.54);
      if (src.normalMap) mat.normalMap = src.normalMap;
      mat.transparent = false;
      mat.opacity = 1.0;
      mat.needsUpdate = true;
      child.material = mat;
      disposables.push(mat);
    });

    // --- normalize to 2.2 units tall, center at origin ---
    const box = new Box3().setFromObject(model);
    const size = new Vector3();
    box.getSize(size);
    const height = size.y || 1;
    model.scale.setScalar(2.2 / height);

    const box2 = new Box3().setFromObject(model);
    const center = new Vector3();
    box2.getCenter(center);
    model.position.sub(center);

    // --- upright the leaning case, then seat it on the plinth top ---
    const alignGroup = new Group();
    alignGroup.add(model);
    alignGroup.rotation.z = -0.3;
    alignGroup.rotation.x = 0.08;
    watchGroup.add(alignGroup);

    const seated = new Box3().setFromObject(alignGroup);
    const seatedCenter = new Vector3();
    seated.getCenter(seatedCenter);
    alignGroup.position.x -= seatedCenter.x;
    alignGroup.position.z -= seatedCenter.z;
    alignGroup.position.y -= seated.min.y + 1.1; // bottom rests at y=-1.1

    // entrance: rise-in + weighted-settle
    watchGroup.position.y = -0.35;
    watchGroup.scale.setScalar(0.96);
    const tl = gsap.timeline();
    tl.to(watchGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' });
    tl.to(
      watchGroup.scale,
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' },
      0.2
    );
    tl.to(
      watchGroup.scale,
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      0.55
    );
    timelines.push(tl);
  });

  // ------------------------------------------------------------------
  // TEXT — verbatim spec copy via fontAtlas, minimal documented opts.
  // Headline baseline 1.5 units below scene center; caption 0.5 below.
  // ------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(0, 0, 1.2);
  root.add(textGroup);

  const textObjs = [];

  for (const item of items) {
    const role = item.role ?? 'body';
    const text = String(item.text ?? '');
    if (role === 'headline') {
      const obj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: cPaper,
        align: 'center',
      });
      obj.position.set(0, -1.5, 0);
      textGroup.add(obj);
      textObjs.push(obj);
    } else if (role === 'body') {
      const obj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 26,
        color: cPaper,
        align: 'center',
      });
      obj.position.set(0, -1.78, 0);
      textGroup.add(obj);
      textObjs.push(obj);
    } else if (role === 'caption') {
      const obj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: colors.accent ?? '#ff2a38',
        align: 'center',
      });
      obj.position.set(0, -2.0, 0);
      textGroup.add(obj);
      textObjs.push(obj);
    }
  }

  // text fade-up entrance
  if (textObjs.length > 0) {
    const tl = gsap.timeline({ delay: 0.25 });
    textObjs.forEach((obj, i) => {
      const finalY = obj.position.y;
      obj.position.y = finalY - 0.2;
      tl.to(obj.position, { y: finalY, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
    timelines.push(tl);
  }

  // ------------------------------------------------------------------
  // CINEMATIC PRIMITIVES — apply every one from config
  // ------------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const handle = fn(watchGroup, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ------------------------------------------------------------------
  // HANDLERS — hover release weighted settle
  // ------------------------------------------------------------------
  root.userData.handlers = {
    pointerout: () => {
      const tl = gsap.timeline();
      tl.to(watchGroup.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.2,
        ease: 'power2.out',
      });
      tl.to(watchGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
  };

  // ------------------------------------------------------------------
  // CLEANUP
  // ------------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    timelines.length = 0;
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    primitiveHandles.length = 0;
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    disposables.length = 0;
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry && typeof child.geometry.dispose === 'function') {
          child.geometry.dispose();
        }
      }
    });
  };

  return root;
}
